def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Locate a uniform separator whose removal leaves equal-sized panels.
    split = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r == h - 1 - r:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - 1 - c:
                split = ("col", c)
                break

    if split[0] == "row":
        k = split[1]
        a, b = grid[:k], grid[k + 1:]
    else:
        k = split[1]
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    background = Counter(v for row in a for v in row).most_common(1)[0][0]
    if common:
        background = min(common)

    return [
        [3 if a[r][c] == b[r][c] else background for c in range(len(a[0]))]
        for r in range(len(a))
    ]
